//go:build conformance

package daemon

// The conformance harness's release for serve_cli (scripts/conformance/
// targets/go-binary.mjs): a directory holding the CLI built from this
// commit and the installers, signed with a test Sigstore generated by
// `varlatchd admin conformance-sign-release` itself, whose trusted root it
// writes beside them. Never in a release build: it has no conformance tag.

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"os"
	"path/filepath"
	"slices"

	"github.com/sigstore/sigstore-go/pkg/root"

	"github.com/varlatch/varlatch/go/lib/release"
	"github.com/varlatch/varlatch/go/lib/release/releasetest"
	"github.com/varlatch/varlatch/go/server/servecli"
)

// cliReleaseVariable names the harness's release directory.
const cliReleaseVariable = "VARLATCH_CONFORMANCE_CLI_RELEASE"

// trustedRootFile is the test Sigstore's trusted root, in that directory.
const trustedRootFile = "trusted_root.json"

func init() {
	conformanceCLIRelease = func(o *servecli.Options, log *slog.Logger) {
		dir := os.Getenv(cliReleaseVariable)
		if dir == "" {
			return
		}
		log.Warn("CONFORMANCE BUILD: serve_cli serves the release in "+cliReleaseVariable+", signed by the harness's test Sigstore, not github.com's; never run this build for real use", "dir", dir)
		o.Source = dirSource(dir)
		o.Trusted = func(context.Context) (root.TrustedMaterial, error) {
			return root.NewTrustedRootFromPath(filepath.Join(dir, trustedRootFile))
		}
	}
	conformanceSignRelease = signRelease
}

// dirSource gives a release's files from a directory, by the fixed names
// servecli asks for.
type dirSource string

func (d dirSource) Get(_ context.Context, name string, limit int64) ([]byte, error) {
	if name != filepath.Base(name) {
		return nil, fmt.Errorf("not a file name: %q", name)
	}
	b, err := os.ReadFile(filepath.Join(string(d), name))
	if errors.Is(err, os.ErrNotExist) {
		return nil, release.ErrNotFound
	}
	if err == nil && int64(len(b)) > limit {
		return nil, fmt.Errorf("%s is larger than %d bytes", name, limit)
	}
	return b, err
}

// signRelease is `varlatchd admin conformance-sign-release <dir>
// <version>`: SHA256SUMS of every file in dir, signed by a test Sigstore
// made now for the release workflow's identity of version, and that
// Sigstore's trusted root.
func signRelease(args []string, stdout, stderr io.Writer) int {
	if len(args) != 2 || !release.ValidVersion(args[1]) {
		fmt.Fprintln(stderr, "usage: varlatchd admin conformance-sign-release <dir> <version>")
		return 64
	}
	dir, version := args[0], args[1]
	entries, err := os.ReadDir(dir)
	if err != nil {
		fmt.Fprintf(stderr, "varlatchd admin conformance-sign-release: %v\n", err)
		return ExitFailure
	}
	files := map[string][]byte{}
	for _, e := range entries {
		if !e.Type().IsRegular() || slices.Contains([]string{servecli.Sums, servecli.Bundle, trustedRootFile}, e.Name()) {
			continue
		}
		if files[e.Name()], err = os.ReadFile(filepath.Join(dir, e.Name())); err != nil {
			fmt.Fprintf(stderr, "varlatchd admin conformance-sign-release: %v\n", err)
			return ExitFailure
		}
	}
	sums := releasetest.Sums(files)
	s := releasetest.New()
	for name, data := range map[string][]byte{
		servecli.Sums:   sums,
		servecli.Bundle: s.Sign(sums, release.Identity(version), release.Issuer),
		trustedRootFile: s.TrustedRootJSON(),
	} {
		if err := os.WriteFile(filepath.Join(dir, name), data, 0o644); err != nil {
			fmt.Fprintf(stderr, "varlatchd admin conformance-sign-release: %v\n", err)
			return ExitFailure
		}
	}
	fmt.Fprintf(stdout, "signed %d files of %s\n", len(files), version)
	return ExitOK
}
